UPDATE "posts" p SET "updated_at" = now(), "body" = (
  SELECT jsonb_agg(e ORDER BY k) FROM (
    SELECT b AS e, n * 1000 AS k FROM jsonb_array_elements(p."body") WITH ORDINALITY AS a(b, n)
    UNION ALL
    SELECT x, coalesce((SELECT min(n) FROM jsonb_array_elements(p."body") WITH ORDINALITY AS c(b, n) WHERE b->>'type' = 'products'),
      jsonb_array_length(p."body") + 1) * 1000 - 500 + m
    FROM jsonb_array_elements($j$[{"type": "h2", "text": "❓ Hỏi nhanh về lan ý"}, {"type": "h3", "text": "Lan ý trồng thủy sinh được không?"}, {"type": "p", "text": "Được. Rửa sạch đất bám rễ, cắt bỏ rễ úng thối, đặt cây vào bình sao cho **nước chỉ ngập phần rễ**, không ngập gốc thân. Thay nước 5–7 ngày một lần, mỗi tháng nhỏ vài giọt phân thủy sinh. Lan ý trồng nước vẫn ra hoa nếu đủ sáng, nhưng thường lớn chậm hơn trồng đất."}, {"type": "h3", "text": "Lá lan ý bị vàng hoặc cháy đầu lá là do đâu?"}, {"type": "p", "text": "Nhiều lá vàng cùng lúc, đất ướt nhão: tưới quá nhiều, rễ bắt đầu thối. Một vài lá già dưới gốc vàng: tự nhiên, cắt bỏ. Đầu lá khô nâu: đất để khô kiệt, nước máy nhiều clo hoặc bón dư phân. Xem cách phân biệt trong bài [lá cháy mép, khô đầu lá](/goc-cham-cay/la-chay-mep-kho-dau-la) và [8 nguyên nhân lá cây bị vàng](/goc-cham-cay/la-cay-bi-vang-nguyen-nhan)."}, {"type": "h3", "text": "Bao lâu thay chậu lan ý một lần?"}, {"type": "p", "text": "Khoảng 12–18 tháng, hoặc khi thấy rễ mọc ra lỗ thoát nước, tưới xong đất khô rất nhanh. Nên thay vào đầu mùa mưa, kết hợp tách bụi nếu cây quá dày. Xem [thay chậu đúng cách](/goc-cham-cay/thay-chau-cay-canh-dung-cach)."}, {"type": "h3", "text": "Lan ý và lan ý nữ hoàng khác nhau thế nào?"}, {"type": "p", "text": "Cùng là Spathiphyllum, cách chăm giống hệt nhau. [Lan ý nữ hoàng](/san-pham/lan-y-nu-hoang) là giống cỡ lớn: lá to bản hơn, hoa trắng cao vượt tán, hợp đặt sàn phòng khách, sảnh. [Lan ý](/san-pham/lan-y) thường gọn hơn, hợp để bàn, kệ."}, {"type": "h3", "text": "Lan ý có lọc không khí, hợp mệnh gì?"}, {"type": "p", "text": "Lan ý hay được nhắc trong danh sách \"cây lọc không khí\", nhưng trong một căn phòng thật, tác dụng của vài chậu cây rất nhỏ — xem [sự thật về nghiên cứu NASA](/goc-cham-cay/cay-canh-loc-khong-khi-that-khong). Về phong thủy, theo quan niệm dân gian lan ý (huệ hòa bình) tượng trưng cho sự bình yên; hoa trắng thường được xếp hợp mệnh **Kim**, **Thủy** — xem [chọn cây theo mệnh](/goc-cham-cay/chon-cay-theo-menh-ngu-hanh)."}]$j$::jsonb) WITH ORDINALITY AS y(x, m)
  ) s)
