UPDATE "posts" p SET "updated_at" = now(), "body" = (
  SELECT jsonb_agg(e ORDER BY k) FROM (
    SELECT b AS e, n * 1000 AS k FROM jsonb_array_elements(p."body") WITH ORDINALITY AS a(b, n)
