    FROM jsonb_array_elements($j$[{"type": "h2", "text": "❓ Hỏi nhanh về phú quý, vạn lộc, ngọc ngân, ngân hậu"}, {"type": "h3", "text": "Phú quý, vạn lộc trồng thủy sinh được không?"}, {"type": "p", "text": "Được — phú quý, ngọc ngân trồng nước khá phổ biến. Rửa sạch đất, cắt rễ hư, đặt cây vào bình sao cho nước chỉ ngập phần rễ, thay nước 5–7 ngày một lần, mỗi tháng thêm vài giọt phân thủy sinh. Đặt bình nơi sáng tán xạ, tránh nắng chiếu thẳng làm rêu mọc trong nước."}, {"type": "h3", "text": "Vì sao lá phú quý, vạn lộc bị vàng?"}, {"type": "p", "text": "Nguyên nhân hay gặp nhất là **tưới quá nhiều**: lá vàng từ dưới lên, gốc mềm, đất có mùi. Một lá già dưới cùng vàng thỉnh thoảng là tự nhiên. Lá mới ra xanh dần, kém đỏ là thiếu sáng. Xem [8 nguyên nhân lá vàng](/goc-cham-cay/la-cay-bi-vang-nguyen-nhan) và [thối rễ](/benh-cay/thoi-re)."}, {"type": "h3", "text": "Cây nào trong nhóm chịu bóng tốt nhất?"}, {"type": "p", "text": "Các giống lá xanh bạc như [ngân hậu](/san-pham/ngan-hau) và [bạch mã](/san-pham/bach-ma-hoang-tu) chịu bóng tốt nhất, hợp văn phòng ít sáng. Giống lá đỏ hồng như [phú quý](/san-pham/phu-quy), [vạn lộc](/san-pham/van-loc) cần sáng hơn để giữ màu."}, {"type": "h3", "text": "Cây ra hoa có nên cắt không?"}, {"type": "p", "text": "Nhóm Aglaonema thỉnh thoảng trổ mo hoa nhỏ màu trắng xanh, giống hoa lan ý thu nhỏ. Hoa không đẹp bằng lá nên nhiều người cắt bỏ sát gốc cuống để cây dồn sức ra lá mới. Để lại cũng không hại gì."}, {"type": "h3", "text": "Nên chọn cây nào làm quà?"}, {"type": "p", "text": "Theo quan niệm dân gian: phú quý, vạn lộc (sắc đỏ, tên gọi tài lộc) hay được chọn tặng khai trương, Tết; ngọc ngân mang ý nghĩa tình cảm bền chặt; bạch mã hay được chọn tặng thăng chức; ngân hậu sắc bạc mang ý sang trọng, bình an. Xem thêm [ý nghĩa tên gọi các cây tài lộc](/goc-cham-cay/y-nghia-ten-goi-cay-tai-loc)."}]$j$::jsonb) WITH ORDINALITY AS y(x, m)
  ) s)
